import React, { useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Grid,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import EditOutlined from '@mui/icons-material/EditOutlined';
import ApiService from '../services/api';
import {
  CIN_NUMBER_REGEX,
  REGISTRATION_FIELD_EXAMPLES,
  UDYAM_NUMBER_REGEX,
} from '../constants/registrationExamples';
import { isValidGstNumber } from '../utils/gstValidation';
import { toNationalIndianMobile } from '../utils/normalizePhoneInput';

const PAN_NUMBER_REGEX = /^[A-Z]{5}[0-9]{4}[A-Z]{1}$/;

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export type MsmeProfileEssentials = {
  companyName?: string;
  industry?: string;
  gstNumber?: string;
  udyamRegistrationNumber?: string;
  panNumber?: string;
  listedCompanyProfile?: {
    cinNumber?: string;
    listingStatus?: string;
    stockExchanges?: string[];
    isin?: string;
    scripCode?: string;
  };
  contact?: {
    email?: string;
    phone?: string;
  };
};

type MsmeProfileEssentialsEditorProps = {
  profile: MsmeProfileEssentials | null;
  onSaved?: () => void | Promise<void>;
};

const MsmeProfileEssentialsEditor: React.FC<MsmeProfileEssentialsEditorProps> = ({
  profile,
  onSaved,
}) => {
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [draft, setDraft] = useState({
    companyName: '',
    industry: '',
    gstNumber: '',
    udyamRegistrationNumber: '',
    cinNumber: '',
    panNumber: '',
    contactPhone: '',
    contactEmail: '',
  });
  const [touched, setTouched] = useState<Record<string, boolean>>({});

  useEffect(() => {
    if (!profile) return;
    setDraft({
      companyName: profile.companyName || '',
      industry: profile.industry || '',
      gstNumber: profile.gstNumber || '',
      udyamRegistrationNumber: profile.udyamRegistrationNumber || '',
      cinNumber: profile.listedCompanyProfile?.cinNumber || '',
      panNumber: profile.panNumber || '',
      contactPhone: profile.contact?.phone || '',
      contactEmail: profile.contact?.email || '',
    });
    setTouched({});
    if (!String(profile.companyName || '').trim() || !String(profile.gstNumber || '').trim()) {
      setEditing(true);
    }
  }, [profile]);

  const fieldErrors = useMemo(() => {
    const errs: Record<string, string> = {};
    if (!draft.companyName.trim()) {
      errs.companyName = 'Company name is required';
    }
    const gstTrimmed = draft.gstNumber.trim().toUpperCase();
    if (!gstTrimmed) {
      errs.gstNumber = 'GST number is required';
    } else if (!isValidGstNumber(gstTrimmed)) {
      errs.gstNumber = 'Invalid GSTIN — must be 15 characters (e.g. 22AAAAA0000A1Z5)';
    }
    const pan = draft.panNumber.trim().toUpperCase();
    if (pan && !PAN_NUMBER_REGEX.test(pan)) {
      errs.panNumber = 'Invalid PAN format';
    }
    if (draft.contactPhone.trim() && !toNationalIndianMobile(draft.contactPhone)) {
      errs.contactPhone = 'Enter a valid 10-digit Indian mobile number';
    }
    const email = draft.contactEmail.trim();
    if (email && !EMAIL_REGEX.test(email)) {
      errs.contactEmail = 'Enter a valid email address';
    }
    const udyam = draft.udyamRegistrationNumber.trim().toUpperCase();
    const cin = draft.cinNumber.trim().toUpperCase();
    if (!udyam && !cin) {
      errs.udyamRegistrationNumber = 'Provide Udyog (UDYAM) number or CIN';
      errs.cinNumber = 'Provide Udyog (UDYAM) number or CIN';
    }
    if (udyam && !UDYAM_NUMBER_REGEX.test(udyam)) {
      errs.udyamRegistrationNumber = 'Invalid Udyog format: UDYAM-XX-00-0000000';
    }
    if (cin && !CIN_NUMBER_REGEX.test(cin)) {
      errs.cinNumber = 'Invalid CIN format (e.g. U72900MH2010PTC123456)';
    }
    return errs;
  }, [draft]);

  const essentialsValid = Object.keys(fieldErrors).length === 0;

  const saveEssentials = async () => {
    setTouched({
      companyName: true,
      gstNumber: true,
      panNumber: true,
      contactPhone: true,
      contactEmail: true,
      udyamRegistrationNumber: true,
      cinNumber: true,
    });
    if (!essentialsValid) {
      setError('Fix the highlighted fields before saving.');
      return;
    }
    setSaving(true);
    setError(null);
    setFeedback(null);
    try {
      const gstTrimmed = draft.gstNumber.trim().toUpperCase();
      const phone = toNationalIndianMobile(draft.contactPhone);
      const email = draft.contactEmail.trim();
      const industry = draft.industry.trim();
      await ApiService.updateMSMEProfile({
        companyName: draft.companyName.trim(),
        ...(industry ? { industry } : {}),
        gstNumber: gstTrimmed,
        udyamRegistrationNumber: draft.udyamRegistrationNumber.trim().toUpperCase(),
        ...(draft.panNumber.trim()
          ? { panNumber: draft.panNumber.trim().toUpperCase() }
          : {}),
        listedCompanyProfile: {
          ...(profile?.listedCompanyProfile || {}),
          cinNumber: draft.cinNumber.trim().toUpperCase(),
        },
        ...((phone || email) ? {
          contact: {
            ...(phone ? { phone } : {}),
            ...(email ? { email } : {}),
          },
        } : {}),
      });
      setFeedback('Company essentials saved.');
      setEditing(false);
      await onSaved?.();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unable to save company details.');
    } finally {
      setSaving(false);
    }
  };

  const fieldDomId = (key: keyof typeof draft): string | undefined => {
    if (key === 'companyName') return 'essentials-company-name';
    if (key === 'gstNumber') return 'essentials-gst-number';
    if (key === 'udyamRegistrationNumber') return 'essentials-udyam';
    if (key === 'cinNumber') return 'essentials-cin';
    return undefined;
  };

  const saveDisabledReason = saving
    ? 'Saving…'
    : !essentialsValid
      ? `Required before saving: ${Object.values(fieldErrors).filter((v, i, a) => a.indexOf(v) === i).join('; ')}.`
      : null;

  const renderField = (
    label: string,
    value: string,
    key: keyof typeof draft,
    options?: { placeholder?: string; helper?: string; required?: boolean }
  ) => {
    if (editing) {
      const showError = Boolean(touched[key] && fieldErrors[key]);
      return (
        <TextField
          fullWidth
          id={fieldDomId(key)}
          label={label}
          value={draft[key]}
          required={options?.required}
          error={showError}
          onBlur={() => setTouched((current) => ({ ...current, [key]: true }))}
          onChange={(e) => {
            const next = (key === 'gstNumber' || key === 'panNumber' || key === 'udyamRegistrationNumber' || key === 'cinNumber')
              ? e.target.value.toUpperCase()
              : e.target.value;
            setDraft((current) => ({ ...current, [key]: next }));
          }}
          placeholder={options?.placeholder}
          helperText={showError ? fieldErrors[key] : options?.helper}
          inputProps={key === 'gstNumber' ? { maxLength: 15 } : undefined}
        />
      );
    }
    return (
      <Box>
        <Typography variant="body2" color="text.secondary">{label}</Typography>
        <Typography variant="body1">{value || 'Not provided'}</Typography>
      </Box>
    );
  };

  return (
    <Card variant="outlined">
      <CardContent>
        <Stack direction="row" justifyContent="space-between" alignItems="flex-start" sx={{ mb: 2 }}>
          <Box>
            <Typography variant="h6" sx={{ fontWeight: 700 }}>
              Company essentials
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 560 }}>
              Workspace unlock needs company name, GST, and export preference below.
              Saving essentials also requires UDYAM or CIN (identity). PAN, phone, and email stay optional.
            </Typography>
          </Box>
          {!editing ? (
            <Button size="small" variant="outlined" startIcon={<EditOutlined />} onClick={() => setEditing(true)}>
              Edit
            </Button>
          ) : null}
        </Stack>

        {feedback ? (
          <Alert severity="success" sx={{ mb: 2 }} data-testid="essentials-save-success">{feedback}</Alert>
        ) : null}
        {error ? (
          <Alert severity="error" sx={{ mb: 2 }} data-testid="essentials-save-error">{error}</Alert>
        ) : null}

        <Grid container spacing={2}>
          <Grid item xs={12} lg={6}>{renderField('Company name', draft.companyName, 'companyName', { required: true })}</Grid>
          <Grid item xs={12} lg={6}>{renderField('Industry', draft.industry, 'industry')}</Grid>
          <Grid item xs={12} lg={6}>
            {renderField('GST number', draft.gstNumber, 'gstNumber', {
              placeholder: REGISTRATION_FIELD_EXAMPLES.gst,
              helper: editing ? '15-character GSTIN (e.g. 22AAAAA0000A1Z5)' : undefined,
            })}
          </Grid>
          <Grid item xs={12} lg={6}>
            {renderField('UDYOG (UDYAM) number', draft.udyamRegistrationNumber, 'udyamRegistrationNumber', {
              placeholder: REGISTRATION_FIELD_EXAMPLES.udyam,
              required: !draft.cinNumber.trim(),
              helper: editing ? 'Required if you do not enter CIN' : undefined,
            })}
          </Grid>
          <Grid item xs={12} lg={6}>
            {renderField('CIN number', draft.cinNumber, 'cinNumber', {
              placeholder: REGISTRATION_FIELD_EXAMPLES.cin,
              required: !draft.udyamRegistrationNumber.trim(),
              helper: editing ? 'Required if you do not enter UDYOG' : undefined,
            })}
          </Grid>
          <Grid item xs={12} lg={6}>
            {renderField('PAN', draft.panNumber, 'panNumber', {
              placeholder: REGISTRATION_FIELD_EXAMPLES.pan,
            })}
          </Grid>
          <Grid item xs={12} lg={6}>
            {renderField('Contact phone', draft.contactPhone, 'contactPhone', {
              placeholder: REGISTRATION_FIELD_EXAMPLES.phone,
            })}
          </Grid>
          <Grid item xs={12} lg={6}>
            {renderField('Contact email', draft.contactEmail, 'contactEmail')}
          </Grid>
        </Grid>

        {editing ? (
          <Stack spacing={1} sx={{ mt: 2 }}>
            {saveDisabledReason && !saving ? (
              <Typography variant="caption" color="text.secondary" data-testid="essentials-save-disabled-reason">
                {saveDisabledReason}
              </Typography>
            ) : null}
            <Stack direction="row" spacing={1}>
              <Button
                variant="contained"
                onClick={() => void saveEssentials()}
                disabled={Boolean(saveDisabledReason)}
              >
                {saving ? 'Saving…' : 'Save essentials'}
              </Button>
              <Button
                variant="text"
                onClick={() => {
                  setEditing(false);
                  setError(null);
                  setFeedback(null);
                  setTouched({});
                  if (profile) {
                    setDraft({
                      companyName: profile.companyName || '',
                      industry: profile.industry || '',
                      gstNumber: profile.gstNumber || '',
                      udyamRegistrationNumber: profile.udyamRegistrationNumber || '',
                      cinNumber: profile.listedCompanyProfile?.cinNumber || '',
                      panNumber: profile.panNumber || '',
                      contactPhone: profile.contact?.phone || '',
                      contactEmail: profile.contact?.email || '',
                    });
                  }
                }}
              >
                Cancel
              </Button>
            </Stack>
          </Stack>
        ) : null}
      </CardContent>
    </Card>
  );
};

export default MsmeProfileEssentialsEditor;
