import React from 'react';
import { Box, Button, Chip, Stack, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import { Link as RouterLink } from 'react-router-dom';
import { GHG_SCOPE_HEX } from '../../constants/carbonVisualization';
import { GHG_SCOPE3_CATEGORY_OPTIONS } from '../../constants/ghgBoundaryBrsr';

const APPROACH_LABEL: Record<string, string> = {
  operational_control: 'We run the plants',
  financial_control: 'We own the finances',
  equity_share: 'We count our ownership %',
};

const INSIDE_FALLBACK: Record<string, string> = {
  operational_control: 'Sites you operate',
  financial_control: 'Sites you finance',
  equity_share: 'Your ownership share',
};

const SCOPE1_SOURCES = [
  { key: 'scope1StationaryCombustion', label: 'Boilers & generators' },
  { key: 'scope1MobileCombustion', label: 'Company vehicles' },
  { key: 'scope1ProcessEmissions', label: 'Process chemistry' },
  { key: 'scope1FugitiveEmissions', label: 'Refrigerant leaks' },
] as const;

const SCOPE3_SHORT: Record<number, string> = {
  1: 'Goods you buy',
  2: 'Machines you buy',
  3: 'Fuel upstream',
  4: 'Inbound freight',
  5: 'Waste',
  6: 'Business travel',
  7: 'Staff commute',
  8: 'Leased assets in',
  9: 'Outbound freight',
  10: 'Customer processing',
  11: 'Product use',
  12: 'End of life',
  13: 'Leased assets out',
  14: 'Franchises',
  15: 'Investments',
};

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

export type BoundaryPictureOrg = {
  companyName?: string;
  consolidationApproach?: string;
  includedLegalEntities?: Array<{ name?: string; relationshipType?: string }>;
  subsidiaries?: Array<{ name?: string; operationalControl?: boolean }>;
  jointVentures?: Array<{ name?: string; operationalControl?: boolean }>;
  holdingCompany?: { name?: string; includedInBoundary?: boolean };
  nonControlledOperationsExcluded?: boolean;
  franchisesOrOutsourcedOperationsTreatment?: string;
};

export type BoundaryPictureOps = {
  reportingPeriodType?: string;
  reportingPeriodEndMonth?: number;
  baseYear?: number;
  scope1StationaryCombustion?: boolean;
  scope1MobileCombustion?: boolean;
  scope1ProcessEmissions?: boolean;
  scope1FugitiveEmissions?: boolean;
  scope2LocationBased?: boolean;
  scope2MarketBased?: boolean;
  scope3CategoriesIncluded?: number[];
};

type BoundaryPictureProps = {
  org: BoundaryPictureOrg;
  operations: BoundaryPictureOps | null;
  operationsSaved: boolean;
};

function uniqueLabels(labels: string[]): string[] {
  const seen = new Set<string>();
  return labels.filter((label) => {
    const key = label.trim().toLowerCase();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function orgGroups(org: BoundaryPictureOrg): { approach: string; inside: string[]; outside: string[] } {
  const approach = org.consolidationApproach || 'operational_control';
  const inside: string[] = [];
  const outside: string[] = [];

  (org.includedLegalEntities || []).forEach((entity) => {
    if (entity.name?.trim()) inside.push(entity.name.trim());
  });
  if (org.holdingCompany?.name?.trim()) {
    const name = org.holdingCompany.name.trim();
    if (org.holdingCompany.includedInBoundary) inside.push(name);
    else outside.push(name);
  }
  (org.subsidiaries || []).forEach((row) => {
    if (!row.name?.trim()) return;
    if (row.operationalControl === false) outside.push(row.name.trim());
    else inside.push(row.name.trim());
  });
  (org.jointVentures || []).forEach((row) => {
    if (!row.name?.trim()) return;
    if (row.operationalControl) inside.push(row.name.trim());
    else outside.push(row.name.trim());
  });
  if (org.nonControlledOperationsExcluded !== false) {
    outside.push('Operations you do not control');
  }
  if (org.franchisesOrOutsourcedOperationsTreatment?.trim()) {
    outside.push(org.franchisesOrOutsourcedOperationsTreatment.trim());
  }
  return {
    approach,
    inside: uniqueLabels(inside.length > 0 ? inside : [INSIDE_FALLBACK[approach] || INSIDE_FALLBACK.operational_control]),
    outside: uniqueLabels(outside),
  };
}

function periodLabel(ops: BoundaryPictureOps): string {
  const year = ops.baseYear || new Date().getFullYear();
  if (ops.reportingPeriodType === 'calendar_year') return `Calendar year ${year}`;
  const month = MONTHS[(Number(ops.reportingPeriodEndMonth) || 3) - 1] || 'March';
  return `Financial year ending ${month} ${year}`;
}

function ScopeLane({
  title,
  color,
  children,
}: {
  title: string;
  color: string;
  children: React.ReactNode;
}) {
  return (
    <Box
      sx={{
        display: 'grid',
        gridTemplateColumns: { xs: '1fr', sm: '92px 1fr' },
        gap: 1,
        alignItems: 'start',
        p: 1.25,
        borderRadius: 2,
        bgcolor: alpha(color, 0.08),
        borderLeft: `4px solid ${color}`,
      }}
    >
      <Typography variant="caption" sx={{ fontWeight: 800, color, letterSpacing: 0.4, pt: 0.4 }}>
        {title}
      </Typography>
      <Stack direction="row" spacing={0.75} flexWrap="wrap" useFlexGap>
        {children}
      </Stack>
    </Box>
  );
}

const BoundaryPicture: React.FC<BoundaryPictureProps> = ({ org, operations, operationsSaved }) => {
  const groups = orgGroups(org);
  const ops: BoundaryPictureOps = operations || {
    reportingPeriodType: 'financial_year',
    reportingPeriodEndMonth: 3,
    baseYear: new Date().getFullYear(),
    scope1StationaryCombustion: true,
    scope1MobileCombustion: true,
    scope1ProcessEmissions: true,
    scope1FugitiveEmissions: true,
    scope2LocationBased: true,
    scope2MarketBased: false,
    scope3CategoriesIncluded: [1, 2, 3, 4, 5, 6, 7, 9],
  };
  const scope3In = new Set(ops.scope3CategoriesIncluded || []);

  return (
    <Box
      data-testid="boundary-picture"
      sx={{
        display: 'grid',
        gridTemplateColumns: { xs: '1fr', md: '1fr 1.15fr' },
        gap: 2,
        mb: 2,
      }}
    >
      <Box
        sx={{
          p: 2,
          borderRadius: 3,
          border: '1px solid',
          borderColor: alpha('#0f766e', 0.35),
          background: `linear-gradient(180deg, ${alpha('#0f766e', 0.1)} 0%, ${alpha('#0f766e', 0.02)} 100%)`,
        }}
      >
        <Typography variant="overline" sx={{ fontWeight: 800, color: '#0f766e' }}>
          Organization boundary
        </Typography>
        <Typography variant="h6" sx={{ fontWeight: 800, mb: 1.5 }}>
          {org.companyName || 'Your company'}
        </Typography>
        <Box
          sx={{
            border: '2px dashed #0f766e',
            borderRadius: 3,
            p: 1.5,
            minHeight: 148,
            bgcolor: 'background.paper',
          }}
        >
          <Chip size="small" label={APPROACH_LABEL[groups.approach] || groups.approach} color="success" sx={{ mb: 1, fontWeight: 700 }} />
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
            Inside the company
          </Typography>
          <Stack direction="row" spacing={0.75} flexWrap="wrap" useFlexGap>
            {groups.inside.map((label) => (
              <Chip key={label} label={label} size="small" sx={{ bgcolor: '#0f766e', color: '#fff', fontWeight: 700 }} />
            ))}
          </Stack>
        </Box>
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1.5, mb: 0.75 }}>
          Outside the boundary
        </Typography>
        <Stack direction="row" spacing={0.75} flexWrap="wrap" useFlexGap>
          {groups.outside.length > 0 ? groups.outside.map((label) => (
            <Chip key={label} label={label} size="small" variant="outlined" />
          )) : (
            <Chip label="Nothing excluded" size="small" variant="outlined" />
          )}
        </Stack>
      </Box>

      <Box
        data-testid="ops-boundary-picture"
        sx={{
          p: 2,
          borderRadius: 3,
          border: '1px solid',
          borderColor: 'divider',
          bgcolor: 'background.paper',
        }}
      >
        <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap sx={{ mb: 0.5 }}>
          <Typography variant="overline" sx={{ fontWeight: 800, color: 'text.secondary' }}>
            Operations boundary
          </Typography>
          <Chip size="small" label={periodLabel(ops)} variant="outlined" />
        </Stack>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
          {operationsSaved
            ? 'Filled chips come from the emissions pages.'
            : 'Operations boundary has not been saved yet. This picture uses the usual starting choices.'}
        </Typography>
        <Stack spacing={1}>
          <ScopeLane title="SCOPE 1" color={GHG_SCOPE_HEX.scope1}>
            {SCOPE1_SOURCES.map((source) => {
              const selected = ops[source.key] !== false;
              return (
                <Chip
                  key={source.key}
                  size="small"
                  label={source.label}
                  variant={selected ? 'filled' : 'outlined'}
                  sx={selected ? { bgcolor: GHG_SCOPE_HEX.scope1, color: '#fff', fontWeight: 700 } : { opacity: 0.55 }}
                />
              );
            })}
          </ScopeLane>
          <ScopeLane title="SCOPE 2" color={GHG_SCOPE_HEX.scope2}>
            <Chip
              size="small"
              label="Grid electricity"
              variant={ops.scope2LocationBased !== false ? 'filled' : 'outlined'}
              sx={ops.scope2LocationBased !== false ? { bgcolor: GHG_SCOPE_HEX.scope2, color: '#fff', fontWeight: 700 } : { opacity: 0.55 }}
            />
            <Chip
              size="small"
              label="Green power contract"
              variant={ops.scope2MarketBased ? 'filled' : 'outlined'}
              sx={ops.scope2MarketBased ? { bgcolor: GHG_SCOPE_HEX.scope2, color: '#fff', fontWeight: 700 } : { opacity: 0.55 }}
            />
          </ScopeLane>
          <ScopeLane title="SCOPE 3" color={GHG_SCOPE_HEX.scope3}>
            {GHG_SCOPE3_CATEGORY_OPTIONS.filter((option) => scope3In.has(option.value)).map((option) => (
              <Chip
                key={option.value}
                size="small"
                label={SCOPE3_SHORT[option.value] || option.label}
                sx={{ bgcolor: GHG_SCOPE_HEX.scope3, color: '#fff', fontWeight: 700 }}
              />
            ))}
            <Chip size="small" variant="outlined" label={`${scope3In.size} of 15 in`} />
          </ScopeLane>
        </Stack>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 1.5 }}>
          <Button component={RouterLink} to="/operations/scope-1" size="small" variant="outlined">Direct emissions</Button>
          <Button component={RouterLink} to="/operations" size="small" variant="outlined">Purchased electricity</Button>
          <Button component={RouterLink} to="/operations/scope-3" size="small" variant="outlined">Value chain</Button>
        </Stack>
      </Box>
    </Box>
  );
};

export default BoundaryPicture;
